1	//! [`ForkdBackend`] — the microVM execution tier: a portable REST client of the
2	//! forkd Firecracker controller. Feature-gated behind `microvm`. **Experimental**
3	//! (SMA-416/SMA-437): the fork→exec→destroy flow is real and egress enforcement
4	//! now exists — after deploying the per-VM netns rules that force traffic through a
5	//! [`EgressProxy`](crate::EgressProxy), call `.enforce_egress(proxy_endpoint)` to
6	//! *attest* that setup and report [`Isolation::Proxied`] from
7	//! `guarantees().network`; the default (no `.enforce_egress`) leaves it
8	//! [`Isolation::None`]. (The netns rules do the routing; the method only probes +
9	//! flips the reported guarantee.)
10	//! The live KVM run is validated via the harness/runbook
11	//! (`docs/runbooks/forkd-live-validation.md`).
12	
13	use std::sync::Arc;
14	use std::time::Duration;
15	
16	use async_trait::async_trait;
17	use paigasus_helikon_core::ToolError;
18	
19	use crate::net::policy::EgressPolicy;
20	
21	use super::{
22	    ExecOutput, ExecRequest, ExecutionBackend, Isolation, SandboxGuarantees, DEFAULT_MAX_OUTPUT,
23	    DEFAULT_TIMEOUT,
24	};
25	
26	const DEFAULT_UA: &str = concat!("paigasus-helikon-tools/", env!("CARGO_PKG_VERSION"));
27	/// Fixed control-plane timeout for the destroy call (the command timeout governs exec).
28	const CONTROL_TIMEOUT: Duration = Duration::from_secs(10);
29	
30	/// Construction-time failures for [`ForkdBackend`]. Runtime failures (daemon
31	/// unreachable, fork/exec error) surface as `ToolError::Other` from `run`.
32	///
33	/// Variants never embed the bearer token — keep auth material out of error text.
34	#[derive(Debug, thiserror::Error)]
35	#[non_exhaustive]
36	pub enum ForkdError {
37	    /// The controller URL could not be parsed.
38	    #[error("invalid forkd controller URL: {0}")]
39	    InvalidUrl(String),
40	    /// A required field (bearer token / snapshot tag) was not set.
41	    #[error("missing required forkd config: {0}")]
42	    MissingConfig(&'static str),
43	    /// The controller CA PEM could not be parsed.
44	    #[error("invalid controller CA certificate")]
45	    InvalidCa,
46	    /// The reqwest client could not be constructed.
47	    #[error("failed to build forkd HTTP client")]
48	    ClientBuild,
49	    /// A plain-`http` controller URL on a non-loopback host — this would send the
50	    /// bearer token in cleartext over the network. Use `https` for remote hosts.
51	    #[error("insecure forkd controller URL: use https for non-loopback hosts")]
52	    InsecureControllerUrl,
53	    /// `enforce_egress` was set but the proxy endpoint could not be reached.
54	    #[error("egress proxy endpoint is unreachable")]
55	    ProxyUnreachable,
56	}
57	
58	/// `POST /v1/sandboxes` request body — fork `n` children (we use 1) copy-on-write
59	/// from a warmed snapshot, each in its own network namespace.
60	#[derive(serde::Serialize)]
61	struct ForkReq<'a> {
62	    snapshot_tag: &'a str,
63	    n: u32,
64	    per_child_netns: bool,
65	}
66	
67	/// One sandbox in the `POST /v1/sandboxes` response **array**. forkd returns more
68	/// fields (snapshot_tag, guest_addr, …); only `id` is needed, the rest are ignored.
69	#[derive(serde::Deserialize)]
70	struct SandboxInfo {
71	    id: String,
72	}
73	
74	/// `POST /v1/sandboxes/{id}/exec` request body. `args` runs verbatim in the guest
75	/// (no shell expansion), so a shell command is wrapped as `["sh","-c","<cmd>"]`.
76	/// `timeout_secs` is the daemon-side cap (we also enforce one client-side).
77	#[derive(serde::Serialize)]
78	struct ExecReq<'a> {
79	    args: [&'a str; 3],
80	    timeout_secs: u64,
81	}
82	
83	/// `POST /v1/sandboxes/{id}/exec` response — captured guest output.
84	#[derive(serde::Deserialize)]
85	struct ExecResp {
86	    #[serde(default)]
87	    stdout: String,
88	    #[serde(default)]
89	    stderr: String,
90	    #[serde(default)]
91	    exit_code: Option<i32>,
92	}
