94	/// Builder for [`ForkdBackend`].
95	pub struct ForkdBackendBuilder {
96	    controller_url: String,
97	    bearer_token: Option<String>,
98	    controller_ca: Option<Vec<u8>>,
99	    snapshot: Option<String>,
100	    timeout: Duration,
101	    max_output_bytes: usize,
102	    egress: EgressPolicy,
103	    enforce_egress: Option<String>,
104	}
105	
106	impl ForkdBackendBuilder {
107	    /// Bearer token presented to the controller (required).
108	    pub fn bearer_token(mut self, token: impl Into<String>) -> Self {
109	        self.bearer_token = Some(token.into());
110	        self
111	    }
112	
113	    /// PEM trust root / cert pin for the controller's TLS (required for a
114	    /// self-signed localhost daemon; use a real CA for a remote host).
115	    pub fn controller_ca(mut self, pem: impl Into<Vec<u8>>) -> Self {
116	        self.controller_ca = Some(pem.into());
117	        self
118	    }
119	
120	    /// Warmed parent snapshot tag to fork children from (required; forkd's
121	    /// `snapshot_tag`).
122	    pub fn snapshot(mut self, tag: impl Into<String>) -> Self {
123	        self.snapshot = Some(tag.into());
124	        self
125	    }
126	
127	    /// Wall-clock timeout for the exec step (default 30s).
128	    pub fn timeout(mut self, timeout: Duration) -> Self {
129	        self.timeout = timeout;
130	        self
131	    }
132	
133	    /// Truncate captured stdout/stderr to this many bytes each (default 1 MiB).
134	    pub fn max_output_bytes(mut self, n: usize) -> Self {
135	        self.max_output_bytes = n;
136	        self
137	    }
138	
139	    /// Egress policy the backend carries. The policy is declared here; call
140	    /// `.enforce_egress()` to attest that it is enforced by the deployed
141	    /// [`EgressProxy`](crate::EgressProxy) + per-VM netns default-deny.
142	    pub fn egress_policy(mut self, policy: EgressPolicy) -> Self {
143	        self.egress = policy;
144	        self
145	    }
146	
147	    /// Attest that the layered egress enforcement (per-VM netns default-deny + the
148	    /// [`EgressProxy`](crate::EgressProxy) at `proxy_endpoint`) is deployed, so
149	    /// `guarantees().network` reports [`Isolation::Proxied`]. `build()` probes the
150	    /// proxy for reachability and fails closed if it cannot connect — but it
151	    /// **cannot** verify the host's netns rules, so this is an operator attestation
152	    /// (the same trust model the kernel/hypervisor tiers use). Without this, the
153	    /// network guarantee stays [`Isolation::None`]. `proxy_endpoint` is `host:port`
154	    /// or a URL.
155	    pub fn enforce_egress(mut self, proxy_endpoint: impl Into<String>) -> Self {
156	        self.enforce_egress = Some(proxy_endpoint.into());
157	        self
158	    }
159	
160	    /// Build into the concrete [`ForkdBackend`] — used by [`Self::build`] and the
161	    /// in-module unit tests. Public callers go through `build()`.
162	    fn into_backend(self) -> Result<ForkdBackend, ForkdError> {
163	        // Validate the controller URL up front. Reject plain `http` to a
164	        // non-loopback host: the bearer token would travel in cleartext, the
165	        // network-MITM threat the TLS-trust story exists to prevent. Loopback
166	        // `http` (forkd's documented default) stays allowed.
167	        let parsed = reqwest::Url::parse(&self.controller_url)
168	            .map_err(|_| ForkdError::InvalidUrl(self.controller_url.clone()))?;
169	        if parsed.scheme() == "http" && !host_is_loopback(&parsed) {
170	            return Err(ForkdError::InsecureControllerUrl);
171	        }
172	        let token = self
173	            .bearer_token
174	            .ok_or(ForkdError::MissingConfig("bearer_token"))?;
175	        let snapshot = self.snapshot.ok_or(ForkdError::MissingConfig("snapshot"))?;
176	        let mut cb = reqwest::Client::builder()
177	            .user_agent(DEFAULT_UA)
178	            .connect_timeout(CONTROL_TIMEOUT);
179	        if let Some(pem) = &self.controller_ca {
180	            let cert = reqwest::Certificate::from_pem(pem).map_err(|_| ForkdError::InvalidCa)?;
181	            cb = cb.add_root_certificate(cert);
182	        }
183	        let client = cb.build().map_err(|_| ForkdError::ClientBuild)?;
184	        let egress_enforced = match &self.enforce_egress {
185	            Some(ep) => {
186	                probe_proxy_reachable(ep).map_err(|_| ForkdError::ProxyUnreachable)?;
187	                true
188	            }
189	            None => false,
190	        };
191	        Ok(ForkdBackend {
192	            client,
193	            base: self.controller_url.trim_end_matches('/').to_string(),
194	            token,
195	            snapshot,
196	            timeout: self.timeout,
197	            max_output_bytes: self.max_output_bytes,
198	            egress: self.egress,
199	            egress_enforced,
200	        })
201	    }
202	
203	    /// Finish building into a shareable `Arc<dyn ExecutionBackend>`.
204	    pub fn build(self) -> Result<Arc<dyn ExecutionBackend>, ForkdError> {
205	        Ok(Arc::new(self.into_backend()?))
206	    }
207	}
208	
209	/// The microVM execution backend — a REST client of the forkd controller. See
210	/// the module docs: experimental skeleton; egress is carried but not enforced.
211	///
212	/// `Debug` is implemented manually to **redact the bearer `token`** — a derived
213	/// `Debug` would leak it into logs/traces.
214	pub struct ForkdBackend {
215	    client: reqwest::Client,
216	    base: String,
217	    token: String,
218	    snapshot: String,
219	    timeout: Duration,
220	    max_output_bytes: usize,
221	    egress: EgressPolicy,
222	    egress_enforced: bool,
223	}
224	
225	impl std::fmt::Debug for ForkdBackend {
226	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
227	        f.debug_struct("ForkdBackend")
228	            .field("base", &self.base)
229	            .field("token", &"<redacted>")
230	            .field("snapshot", &self.snapshot)
231	            .field("timeout", &self.timeout)
232	            .field("max_output_bytes", &self.max_output_bytes)
233	            .field("egress", &self.egress)
234	            .finish_non_exhaustive()
235	    }
236	}
237	
238	impl ForkdBackend {
239	    /// Start building a backend against the controller at `controller_url`
240	    /// (e.g. `"https://127.0.0.1:8889"`). Defaults: 30s timeout, 1 MiB output
241	    /// cap, `EgressPolicy::deny_all()`.
242	    pub fn builder(controller_url: impl Into<String>) -> ForkdBackendBuilder {
243	        ForkdBackendBuilder {
244	            controller_url: controller_url.into(),
245	            bearer_token: None,
246	            controller_ca: None,
247	            snapshot: None,
248	            timeout: DEFAULT_TIMEOUT,
249	            max_output_bytes: DEFAULT_MAX_OUTPUT,
250	            egress: EgressPolicy::deny_all(),
251	            enforce_egress: None,
252	        }
253	    }
254	
255	    /// The egress policy this backend carries. This accessor reads the declared
256	    /// policy; enforcement is attested via `.enforce_egress()` at build time
257	    /// (see its doc for the trust model).
258	    pub fn egress_policy(&self) -> &EgressPolicy {
259	        &self.egress
260	    }
261	
262	    async fn post_json<T: serde::de::DeserializeOwned>(
263	        &self,
264	        url: &str,
265	        body: &impl serde::Serialize,
266	    ) -> Result<T, ToolError> {
267	        // The bearer token rides only in the Authorization header — never in
268	        // the URL/body — so reqwest's error Display (URL only) cannot leak it.
269	        let resp = self
270	            .client
271	            .post(url)
272	            .bearer_auth(&self.token)
273	            .json(body)
274	            .send()
275	            .await
276	            .map_err(|e| ToolError::Other(anyhow::anyhow!("forkd request failed: {e}")))?;
277	        if !resp.status().is_success() {
278	            return Err(ToolError::Other(anyhow::anyhow!(
279	                "forkd controller returned HTTP {}",
280	                resp.status().as_u16()
281	            )));
282	        }
283	        resp.json::<T>()
284	            .await
285	            .map_err(|e| ToolError::Other(anyhow::anyhow!("forkd response decode failed: {e}")))
286	    }
287	
288	    async fn fork(&self) -> Result<String, ToolError> {
289	        let url = format!("{}/v1/sandboxes", self.base);
290	        let body = ForkReq {
291	            snapshot_tag: &self.snapshot,
292	            n: 1,
293	            per_child_netns: true,
294	        };
295	        // Fork returns an array (n children); we requested 1, so take the first.
296	        let list: Vec<SandboxInfo> =
297	            tokio::time::timeout(self.timeout, self.post_json(&url, &body))
298	                .await
299	                .map_err(|_| ToolError::Other(anyhow::anyhow!("forkd: fork timed out")))??;
300	        list.into_iter()
301	            .next()
302	            .map(|s| s.id)
303	            .ok_or_else(|| ToolError::Other(anyhow::anyhow!("forkd returned no sandbox")))
304	    }
305	
306	    async fn exec(&self, id: &str, command: &str) -> Result<ExecResp, ToolError> {
307	        let url = format!("{}/v1/sandboxes/{id}/exec", self.base);
308	        // `args` runs verbatim in the guest, so wrap the shell command.
309	        self.post_json(
310	            &url,
311	            &ExecReq {
312	                args: ["sh", "-c", command],
313	                timeout_secs: self.timeout.as_secs(),
314	            },
315	        )
316	        .await
317	    }
318	
319	    async fn destroy(&self, id: &str) {
320	        // Best-effort teardown; failures here are not surfaced to the model.
321	        let url = format!("{}/v1/sandboxes/{id}", self.base);
322	        let _ = self
323	            .client
324	            .delete(&url)
325	            .bearer_auth(&self.token)
326	            .send()
327	            .await;
328	    }
329	}
330	
331	/// Best-effort reachability probe: a short TCP connect to the proxy endpoint.
332	/// Sync (callable from the sync `build()`), uses `std::net` with a 3-second timeout.
333	/// Accepts `host:port` or a URL (strips `http://`/`https://` scheme if present).
334	/// Iterates ALL resolved addresses and returns `Ok(())` on the first successful
335	/// connect, so a mix of unreachable IPv6 and reachable IPv4 addresses does not
336	/// cause a false failure.
337	fn probe_proxy_reachable(endpoint: &str) -> std::io::Result<()> {
338	    use std::net::ToSocketAddrs;
339	    // Strip a scheme and trailing slash if present.
340	    let hostport = endpoint
341	        .strip_prefix("http://")
342	        .or_else(|| endpoint.strip_prefix("https://"))
343	        .unwrap_or(endpoint)
344	        .trim_end_matches('/');
345	    let addrs: Vec<_> = hostport.to_socket_addrs()?.collect();
346	    if addrs.is_empty() {
347	        return Err(std::io::Error::new(
348	            std::io::ErrorKind::NotFound,
349	            "no addresses resolved",
350	        ));
351	    }
352	    let timeout = std::time::Duration::from_secs(3);
353	    let mut last_err = std::io::Error::new(std::io::ErrorKind::NotFound, "no addresses resolved");
354	    for addr in addrs {
355	        match std::net::TcpStream::connect_timeout(&addr, timeout) {
356	            Ok(_) => return Ok(()),
357	            Err(e) => last_err = e,
358	        }
359	    }
360	    Err(last_err)
361	}
362	
363	/// `true` if `url`'s host is loopback (`localhost`, `127.0.0.0/8`, or `::1`), so a
364	/// plain-`http` controller there does not expose the bearer token to the network.
365	fn host_is_loopback(url: &reqwest::Url) -> bool {
366	    let Some(host) = url.host_str() else {
367	        return false;
368	    };
369	    // `host_str` may keep IPv6 brackets (`[::1]`); strip them before comparing.
370	    let host = host.trim_start_matches('[').trim_end_matches(']');
371	    host.eq_ignore_ascii_case("localhost")
372	        || host == "::1"
373	        || host
374	            .parse::<std::net::Ipv4Addr>()
375	            .is_ok_and(|ip| ip.is_loopback())
376	}
377	
378	/// Truncate `s` to `cap` bytes on a char boundary; returns `(s, truncated)`.
379	fn truncate(mut s: String, cap: usize) -> (String, bool) {
380	    if s.len() <= cap {
381	        return (s, false);
382	    }
383	    let mut end = cap;
384	    while end > 0 && !s.is_char_boundary(end) {
385	        end -= 1;
386	    }
387	    s.truncate(end);
388	    (s, true)
389	}
