391	#[async_trait]
392	impl ExecutionBackend for ForkdBackend {
393	    async fn run(&self, req: ExecRequest) -> Result<ExecOutput, ToolError> {
394	        // Accepted skeleton gap: if the controller commits a fork but we fail to
395	        // read its id (decode error / client timeout after commit), that sandbox
396	        // is orphaned — we have no id to DELETE. SMA-437 adds GC/reconciliation.
397	        let id = self.fork().await?;
398	        // The wall-clock command timeout governs exec; teardown always runs.
399	        let exec_result = tokio::time::timeout(self.timeout, self.exec(&id, &req.command)).await;
400	        let _ = tokio::time::timeout(CONTROL_TIMEOUT, self.destroy(&id)).await;
401	        match exec_result {
402	            Ok(Ok(resp)) => {
403	                let (stdout, t1) = truncate(resp.stdout, self.max_output_bytes);
404	                let (stderr, t2) = truncate(resp.stderr, self.max_output_bytes);
405	                Ok(ExecOutput::new(
406	                    stdout,
407	                    stderr,
408	                    resp.exit_code,
409	                    false,
410	                    t1 || t2,
411	                ))
412	            }
413	            Ok(Err(e)) => Err(e),
414	            Err(_) => Ok(ExecOutput::new(
415	                String::new(),
416	                String::new(),
417	                None,
418	                true,
419	                false,
420	            )),
421	        }
422	    }
423	
424	    fn guarantees(&self) -> SandboxGuarantees {
425	        let network = if self.egress_enforced {
426	            Isolation::Proxied
427	        } else {
428	            Isolation::None
429	        };
430	        SandboxGuarantees::new(
431	            Isolation::Virtualized, // filesystem — separate guest kernel + rootfs
432	            network,                // network — Proxied when enforce_egress is set
433	            Isolation::Virtualized, // syscalls — guest kernel, not a host filter
434	            "forkd (firecracker microvm — experimental)",
435	        )
436	    }
437	}
