439	#[cfg(test)]
440	mod tests {
441	    use super::*;
442	
443	    #[test]
444	    fn fork_and_exec_responses_deserialize() {
445	        // Fork returns an ARRAY of sandboxes (even for n:1); we take the first.
446	        // Unknown fields (snapshot_tag, …) are ignored.
447	        let v: Vec<SandboxInfo> =
448	            serde_json::from_str(r#"[{"id":"sb-9","snapshot_tag":"t"}]"#).unwrap();
449	        assert_eq!(v[0].id, "sb-9");
450	        // exit_code may be absent (killed by signal) -> None.
451	        let e: ExecResp =
452	            serde_json::from_str(r#"{"stdout":"hi","stderr":"","exit_code":0}"#).unwrap();
453	        assert_eq!(e.stdout, "hi");
454	        assert_eq!(e.exit_code, Some(0));
455	        let e2: ExecResp = serde_json::from_str(r#"{}"#).unwrap();
456	        assert_eq!(e2.stdout, "");
457	        assert_eq!(e2.exit_code, None);
458	    }
459	
460	    #[test]
461	    fn requests_serialize_to_forkd_shapes() {
462	        // Pins the wire shape and exercises the request structs.
463	        let f = serde_json::to_value(ForkReq {
464	            snapshot_tag: "t",
465	            n: 1,
466	            per_child_netns: true,
467	        })
468	        .unwrap();
469	        assert_eq!(f["snapshot_tag"], "t");
470	        assert_eq!(f["n"], 1);
471	        assert_eq!(f["per_child_netns"], true);
472	        let e = serde_json::to_value(ExecReq {
473	            args: ["sh", "-c", "echo hi"],
474	            timeout_secs: 30,
475	        })
476	        .unwrap();
477	        assert_eq!(e["args"][0], "sh");
478	        assert_eq!(e["args"][2], "echo hi");
479	        assert_eq!(e["timeout_secs"], 30);
480	    }
