515	    #[test]
516	    fn builder_carries_egress_policy_and_requires_fields() {
517	        // Missing snapshot -> construction error.
518	        let err = ForkdBackend::builder("https://localhost:8080")
519	            .bearer_token("t")
520	            .into_backend()
