534	    #[test]
535	    fn rejects_insecure_remote_http_controller() {
536	        // Remote plain-HTTP would leak the bearer token in cleartext — rejected.
537	        let err = ForkdBackend::builder("http://forkd.example.com:8889")
538	            .bearer_token("t")
539	            .snapshot("s")
540	            .into_backend()
541	            .unwrap_err();
542	        assert!(matches!(err, ForkdError::InsecureControllerUrl));
543	        // Loopback plain-HTTP (forkd's documented default) is allowed.
544	        assert!(ForkdBackend::builder("http://127.0.0.1:8889")
545	            .bearer_token("t")
546	            .snapshot("s")
547	            .into_backend()
548	            .is_ok());
549	        // HTTPS to a remote host is allowed.
550	        assert!(ForkdBackend::builder("https://forkd.example.com:8889")
551	            .bearer_token("t")
552	            .snapshot("s")
553	            .into_backend()
554	            .is_ok());
555	    }
