11	use paigasus_helikon_tools::{EgressPolicy, ExecRequest, ForkdBackend};
12	
13	/// Returns `(url, token, snapshot)` if all three env vars are set, otherwise
14	/// prints a loud skip message to stderr and returns `None`.
15	fn live_env() -> Option<(String, String, String)> {
16	    match (
17	        std::env::var("FORKD_URL"),
18	        std::env::var("FORKD_TOKEN"),
19	        std::env::var("FORKD_SNAPSHOT"),
20	    ) {
21	        (Ok(u), Ok(t), Ok(s)) => Some((u, t, s)),
22	        _ => {
23	            eprintln!(
24	                "SKIP live forkd test: set FORKD_URL, FORKD_TOKEN, FORKD_SNAPSHOT \
25	                 (+ optional FORKD_CA path, FORKD_PROXY) to run against a live KVM controller"
26	            );
27	            None
28	        }
29	    }
30	}
31	
32	/// Build a backend from the live environment. `enforce` wires in `.enforce_egress`
33	/// using `FORKD_PROXY` (required when `enforce == true`).
34	fn backend(enforce: bool) -> Option<std::sync::Arc<dyn paigasus_helikon_tools::ExecutionBackend>> {
35	    let (url, token, snapshot) = live_env()?;
36	    let mut b = ForkdBackend::builder(url)
37	        .bearer_token(token)
38	        .snapshot(snapshot);
39	    if let Ok(ca_path) = std::env::var("FORKD_CA") {
40	        b = b.controller_ca(std::fs::read(ca_path).expect("FORKD_CA file readable"));
41	    }
42	    if enforce {
43	        let Ok(proxy) = std::env::var("FORKD_PROXY") else {
44	            eprintln!(
45	                "SKIP enforced-egress test: set FORKD_PROXY to run against a live egress proxy"
46	            );
47	            return None;
48	        };
49	        b = b
50	            .egress_policy(EgressPolicy::deny_all().allow_domains(["example.com"]))
51	            .enforce_egress(proxy);
52	    }
53	    Some(b.build().expect("backend builds"))
54	}
