    async fn get_json<T: serde::de::DeserializeOwned>(&self, url: &str) -> Result<T, ToolError> {
        // Mirrors post_json: bearer in the header only; error text carries the URL,
        // never the token.
        let resp = self
            .client
            .get(url)
            .bearer_auth(&self.token)
            .send()
            .await
